"use client";

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { AlertCircle, Loader2, FileText, Calendar, X, Clock } from "lucide-react";
import { motion } from "framer-motion";
import Layout from "./Layout";

export default function ReportHistory() {
  const [absences, setAbsences] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedAbsence, setSelectedAbsence] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/"); // Redirect to login if no token
      return;
    }

    const fetchAbsences = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL}/api/absence/my-absences`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        const data = await response.json();
        if (response.ok) {
          setAbsences(data.data || []);
        } else {
          setError(data.message || "Échec de la récupération des absences.");
        }
      } catch (error) {
        setError("Erreur réseau. Veuillez réessayer.");
      } finally {
        setLoading(false);
      }
    };

    fetchAbsences();
  }, [navigate]);

  const openAbsenceModal = (absence) => setSelectedAbsence(absence);
  const closeAbsenceModal = () => setSelectedAbsence(null);

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50"
        >
          {/* Header with improved gradient and spacing */}
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6 flex items-center">
            <div className="bg-white/10 p-3 rounded-full mr-4">
              <FileText className="h-8 w-8" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight">Historique des absences</h1>
              <p className="text-white/80 mt-1 text-sm">Consultez vos demandes d'absence soumises</p>
            </div>
          </div>

          {error && (
            <div className="p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 m-4 rounded-r-md">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-sm text-red-700">{error}</p>
            </div>
          )}

          <div className="p-6">
            {loading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-sm font-medium">Chargement des absences...</p>
                </div>
              </div>
            ) : absences.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-64 text-gray-500">
                <FileText className="h-12 w-12 text-gray-300 mb-3" />
                <p className="text-center">Aucune absence trouvée</p>
              </div>
            ) : (
              <ul className="space-y-4">
                {absences.map((absence) => (
                  <li
                    key={absence._id}
                    className="p-5 bg-gray-50 rounded-xl hover:bg-[#F5F6FA] transition-colors duration-150 cursor-pointer border border-transparent hover:border-[#C8A45D/30]/50 shadow-sm"
                    onClick={() => openAbsenceModal(absence)}
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center mb-2">
                          <span
                            className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                              absence.status === "approved"
                                ? "bg-green-100 text-green-800"
                                : absence.status === "rejected"
                                ? "bg-red-100 text-red-800"
                                : "bg-yellow-100 text-yellow-800"
                            }`}
                          >
                            {absence.status === "approved" ? "Approuvé" : absence.status === "rejected" ? "Rejeté" : "En attente"}
                          </span>
                          <span className="ml-2 text-xs text-gray-400 flex items-center">
                            <Calendar className="h-4 w-4 mr-1 text-gray-400" />
                            {new Date(absence.startDate).toLocaleDateString("fr-FR")}
                          </span>
                        </div>
                        <p className="text-sm text-gray-700 mb-2">{absence.reason}</p>
                        <div className="flex items-center">
                          <p className="text-xs text-gray-500 flex items-center">
                            <Clock className="h-4 w-4 mr-1 text-gray-500" />
                            {new Date(absence.createdAt).toLocaleDateString("fr-FR")}
                          </p>
                        </div>
                      </div>
                      <div className="ml-4 flex-shrink-0">
                        <div className="h-8 w-8 rounded-full bg-[#F5F6FA] flex items-center justify-center">
                          <svg className="h-4 w-4 text-[#00717F]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                          </svg>
                        </div>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </motion.div>
      </div>

      {/* Modal for Absence Details */}
      {selectedAbsence && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.2 }}
            className="bg-white rounded-xl p-0 w-full max-w-md shadow-2xl overflow-hidden"
          >
            <div className="bg-[#00717F] text-white p-4 flex justify-between items-center">
              <h3 className="text-xl font-semibold">Détails de l'absence</h3>
              <button
                onClick={closeAbsenceModal}
                className="rounded-full p-1 hover:bg-white/20 transition-colors"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-5">
              <div
                className={`p-3 rounded-lg border ${
                  selectedAbsence.status === "approved"
                    ? "bg-green-50 border-green-100"
                    : selectedAbsence.status === "rejected"
                    ? "bg-red-50 border-red-100"
                    : "bg-yellow-50 border-yellow-100"
                }`}
              >
                <p className="text-sm font-medium text-gray-700 mb-1">Statut</p>
                <p
                  className={`font-medium ${
                    selectedAbsence.status === "approved"
                      ? "text-green-800"
                      : selectedAbsence.status === "rejected"
                      ? "text-red-800"
                      : "text-yellow-800"
                  }`}
                >
                  {selectedAbsence.status === "approved" ? "Approuvé" : selectedAbsence.status === "rejected" ? "Rejeté" : "En attente"}
                </p>
              </div>
              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">Raison</p>
                <p className="text-gray-900 bg-gray-50 p-3 rounded-lg border border-gray-100">{selectedAbsence.reason}</p>
              </div>
              <div className="flex items-start space-x-3">
                <div>
                  <p className="text-sm font-medium text-gray-700">Dates</p>
                  <p className="text-gray-900 flex items-center">
                    <Calendar className="h-4 w-4 mr-2 text-gray-500" />
                    {new Date(selectedAbsence.startDate).toLocaleDateString("fr-FR")} -{" "}
                    {new Date(selectedAbsence.endDate).toLocaleDateString("fr-FR")}
                  </p>
                </div>
              </div>
              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">Date de Soumission</p>
                <p className="text-gray-900 flex items-center">
                  <Clock className="h-4 w-4 mr-2 text-gray-500" />
                  {new Date(selectedAbsence.createdAt).toLocaleString("fr-FR")}
                </p>
              </div>
            </div>
            <div className="border-t border-gray-100 p-4 bg-gray-50 flex justify-end">
              <button
                onClick={closeAbsenceModal}
                className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#C8A45D] transition-colors duration-150 font-medium"
              >
                Fermer
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </Layout>
  );
}
